x = [1 3 3 3 2 5 5 6 6 4 4 7 2 2 8];
[p, l] = find_local_peaks(x, -Inf, 1);
assert(isequal(l, [2 8 12]) && isequal(p, [3 6 7]), 'example');
[p, l] = find_local_peaks(x, -Inf, 5);
assert(isequal(l, [2 12]) && isequal(p, [3 7]), 'example with spacing');
[p, l] = find_local_peaks(x', 4, 1);
assert(isequal(size(l), [1 2]) && isequal(l, [8 12]), 'height threshold, row output for column input');
s = [0.721 0.714 0.284 0.229 0.518 0.665 0.765 1.207 1.66 1.371 0.467 -0.033 0.307 0.755 0.618 0.174 -0.093 -0.381 -0.967 -1.362 -0.989 -0.307 -0.298 -0.999 -1.475 -1.245 -0.813 -0.591 -0.285 0.255 0.467 0.022 -0.37 0.094 1.044 1.479 1.216 0.927 0.889 0.726 0.412 0.501 1.041 1.18 0.41 -0.555 -0.801 -0.492 -0.38 -0.56 -0.601 -0.589 -1.006 -1.628 -1.588 -0.739 -0.026 -0.125 -0.536 -0.524 -0.209 -0.032 0.196 0.834 1.44 1.259 0.515 0.237 0.755 1.289 1.232 0.917 0.747 0.442 -0.212 -0.637 -0.294 0.264 0.078 -0.782 -1.365 -1.291 -1.08 -1.04 -0.823 -0.36 -0.273 -0.817 -1.196 -0.662 0.323 0.785 0.643 0.549 0.673 0.62 0.457 0.765 1.491 1.721 1.025 0.182 0.037 0.337 0.376 0.159 0.091 -0.014 -0.626 -1.414 -1.485 -0.783 -0.287 -0.575 -1.081 -1.139 -0.943 -0.869 -0.636 0.076];
[p, l] = find_local_peaks(s, -Inf, 1);
assert(isequal(l, [9 14 23 31 36 44 49 52 57 65 70 78 87 92 95 100 105 113]) && isequal(p, [1.66 0.755 -0.298 0.467 1.479 1.18 -0.38 -0.589 -0.026 1.44 1.289 0.264 -0.273 0.785 0.673 1.721 0.376 -0.287]), 'all peaks of a composite wave');
[p, l] = find_local_peaks(s, 0.5, 1);
assert(isequal(l, [9 14 36 44 65 70 92 95 100]), 'peaks above 0.5');
[p, l] = find_local_peaks(s, -Inf, 12);
assert(isequal(l, [9 23 36 49 65 78 100 113]) && isequal(p, [1.66 -0.298 1.479 -0.38 1.44 0.264 1.721 -0.287]), 'peaks at least 12 samples apart');
[p, l] = find_local_peaks([0 2 0 2 0], -Inf, 3);
assert(isequal(l, 2) && isequal(p, 2), 'equal heights: the earlier one wins');
[p, l] = find_local_peaks([5 4 3 2 1], -Inf, 1);
assert(isequal(size(l), [1 0]) && isequal(size(p), [1 0]), 'monotone signal has no peaks');
[p, l] = find_local_peaks([1 4 4 4], -Inf, 1);
assert(isempty(l), 'plateau at the end is not a peak');
